rows = [[1]*11 for _ in range(28)]
pts={0:[7],2:[3,7,9],4:[1,2],5:[7],6:[5],7:[5],11:[8],13:[0,8],14:[4],15:[1,4,10],17:[0],20:[3,4,9],21:[5,7],22:[1],23:[3,7],27:[5,9]}
for r,cs in pts.items():
    for c in cs: rows[r][c]=7
# horizontal spans between adjacent marks in a row
for r in range(28):
    cs=sorted(c for rr,c in [(rr,c) for rr,cs in pts.items() for c in cs] if rr==r)
    for a,b in zip(cs,cs[1:]):
        for c in range(a+1,b): rows[r][c]=3
# vertical spans between adjacent marks in each col
for c in range(11):
    rs=sorted(r for r,cs in pts.items() if c in cs)
    for a,b in zip(rs,rs[1:]):
        for r in range(a+1,b): rows[r][c]=3
print('\n'.join(' '.join(map(str,r)) for r in rows))
